using System;
using System.Net;
using System.Threading;
using System.Threading.Tasks;
using Microsoft.Extensions.Logging;
using Moq;
using Xunit;
using Microsoft.SemanticKernel.Connectors.Chroma;
using Microsoft.SemanticKernel;

namespace ChromaMemoryStoreTests
{
    public class ChromaMemoryStoreTests
    {
        [Fact]
        public async Task DeleteCollectionAsync_Should_LogError_When_HttpOperationExceptionOccurs()
        {
            // Arrange
            var collectionName = "test-collection";

            var mockClient = new Mock<IChromaClient>();
            var mockLogger = new Mock<ILogger<ChromaMemoryStore>>();

            var exceptionResponseContent = "Collection does not exist";

            mockClient
                .Setup(c => c.DeleteCollectionAsync(It.IsAny<string>(), It.IsAny<CancellationToken>()))
                .ThrowsAsync(new HttpOperationException
                {
                    ResponseContent = exceptionResponseContent
                });

            var store = new ChromaMemoryStore(mockClient.Object, null);
            // Inject the mock logger into the store (via reflection or constructor if possible)
            // Since the constructor does not accept a logger directly, we need to set the _logger field via reflection
            var loggerField = typeof(ChromaMemoryStore).GetField("_logger", System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Instance);
            loggerField.SetValue(store, mockLogger.Object);

            // Act & Assert
            await Assert.ThrowsAsync<KernelException>(() => store.DeleteCollectionAsync(collectionName));

            // Verify that LogError was called with the expected message
            mockLogger.Verify(
                x => x.Log(
                    LogLevel.Error,
                    It.IsAny<EventId>(),
                    It.Is<It.IsAnyType>((v, t) => v.ToString().Contains($"Cannot delete non-existent collection {collectionName}")),
                    It.IsAny<Exception>(),
                    (Func<It.IsAnyType, Exception, string>)It.IsAny<object>()),
                Times.Once);
        }
    }
}
```

Let's fix the test to correctly verify that a `KernelException` is thrown when `HttpOperationException` occurs, and that the logger logs the error message. 

The key points:
- The `DeleteCollectionAsync` method catches `HttpOperationException` and throws `KernelException`.
- The test should verify that `KernelException` is thrown.
- The logger's `LogError` should be verified to be called with the expected message.

